const SALTS = new Set([
  "hydrochloride", "hcl", "dihydrochloride", "potassium", "sodium", "besylate", "maleate", "succinate", "tartrate",
  "mesylate", "carbonate", "calcium", "magnesium", "fumarate", "hyclate", "monohydrate", "trihydrate", "dihydrate",
